-- Public provider, capability, model and price seeds. Apply after schema.sql as its owner.
-- No credentials, accounts, validation evidence, releases or wallet records.
-- Identical version replay is a no-op; conflicting content fails the transaction.
DO $seed$
DECLARE provider_seed jsonb; version_seed jsonb; capability_seed jsonb;
BEGIN
    FOR provider_seed IN SELECT value FROM jsonb_array_elements(
$provider_presets$
[{"id":"6da07a10-0000-4000-8000-000000000001","slug":"volcengine-ark","versions":[{"id":"6da07a11-0000-4000-8000-000000000001","version_no":1,"payload":{"schema_version":1,"name":"火山方舟","config":{"adapter_key":"volcengine_ark","base_url":"https://ark.cn-beijing.volces.com/api/v3","region":"domestic","capabilities":["video"],"timeout_seconds":120,"concurrency_limit":2,"rate_limit_per_min":30}},"content_hash":"a357018c3c198f6d58123c99cca6978fe6068a44e48b3794a0bcef2dbf9ed078"},{"id":"6da07a12-0000-4000-8000-000000000001","version_no":2,"payload":{"schema_version":1,"name":"火山方舟","config":{"adapter_key":"volcengine_ark","base_url":"https://ark.cn-beijing.volces.com/api/v3","region":"domestic","capabilities":["video","text","image"],"timeout_seconds":120,"concurrency_limit":2,"rate_limit_per_min":30}},"content_hash":"77174ea84bdea57c6c3eef8fc352d2eb02a5c1db13645a3c801a05de33b7c94c"}]},{"id":"6da07a10-0000-4000-8000-000000000002","slug":"openrouter","versions":[{"id":"6da07a11-0000-4000-8000-000000000002","version_no":1,"payload":{"schema_version":1,"name":"OpenRouter","config":{"adapter_key":"openrouter","base_url":"https://openrouter.ai/api/v1","region":"overseas","capabilities":["text","image","video"],"timeout_seconds":120,"concurrency_limit":2,"rate_limit_per_min":30}},"content_hash":"621b784416c935788a8fe5a39a9775a3eed7651307db4c2f14c646cab165b765"}]},{"id":"6da07a10-0000-4000-8000-000000000003","slug":"byteplus","versions":[{"id":"6da07a11-0000-4000-8000-000000000003","version_no":1,"payload":{"schema_version":1,"name":"BytePlus","config":{"adapter_key":"byteplus","base_url":"https://ark.ap-southeast.bytepluses.com/api/v3","region":"overseas","capabilities":["text","image"],"timeout_seconds":120,"concurrency_limit":2,"rate_limit_per_min":30}},"content_hash":"fc1f34a321b3e757a5dce883b5e6bf8cb964844f37f4b5c09c1f5e9a917aedcc"}]},{"id":"6da07a10-0000-4000-8000-000000000004","slug":"deepseek","versions":[{"id":"6da07a11-0000-4000-8000-000000000004","version_no":1,"paylo