$provider_presets$::jsonb) LOOP
        INSERT INTO catalog.provider_preset(id,slug,origin)
        VALUES ((provider_seed->>'id')::uuid,provider_seed->>'slug','builtin')
        ON CONFLICT (slug) DO NOTHING;
        IF NOT EXISTS (SELECT 1 FROM catalog.provider_preset WHERE id=(provider_seed->>'id')::uuid AND slug=provider_seed->>'slug' AND origin='builtin') THEN
            RAISE EXCEPTION 'public provider seed identity conflict: %', provider_seed->>'slug';
        END IF;
        FOR version_seed IN SELECT value FROM jsonb_array_elements(provider_seed->'versions') LOOP
            INSERT INTO catalog.provider_preset_version(id,preset_id,version_no,payload,content_hash)
            VALUES ((version_seed->>'id')::uuid,(provider_seed->>'id')::uuid,(version_seed->>'version_no')::integer,version_seed->'payload',version_seed->>'content_hash')
            ON CONFLICT (preset_id,version_no) DO NOTHING;
            IF NOT EXISTS (SELECT 1 FROM catalog.provider_preset_version WHERE id=(version_seed->>'id')::uuid AND preset_id=(provider_seed->>'id')::uuid AND version_no=(version_seed->>'version_no')::integer AND payload=version_seed->'payload' AND content_hash=version_seed->>'content_hash') THEN
                RAISE EXCEPTION 'public preset seed version conflict: %',version_seed->>'id';
            END IF;
        END LOOP;
    END LOOP;
    FOR capability_seed IN SELECT value FROM jsonb_array_elements(
$capability_presets$
[{"id":"6da07a12-0000-4000-8000-000000000001","key":"text.generate","output_type":"json","modes":["text_to_text"],"input_roles":["prompt"]},{"id":"6da07a12-0000-4000-8000-000000000002","key":"image.generate","output_type":"image","modes":["text2image","image2image"],"input_roles":["prompt","reference_image","subject"]},{"id":"6da07a12-0000-4000-8000-000000000003","key":"video.generate","output_type":"video","modes":["omni_reference","image2video","motion","text2video","avatar"],"input_roles":["driving_video","character_image","last_frame","reference_audio","driving_audio","reference_image","prompt","subject","reference_video","first_frame"]},{"id":"6da07a12-0000-4000-8000-000000000004","key":"audio.generate","output_type":"audio","modes":["omni_audio","music_instrumental","text2audio","music_song"],"input_roles":["reference_audio","reference_image","prompt"]}]
$capability_presets$::jsonb) LOOP
        INSERT INTO catalog.capability(id,key,output_type,modes,input_roles)
        VALUES ((capability_seed->>'id')::uuid,capability_seed->>'key',capability_seed->>'output_type',ARRAY(SELECT jsonb_array_elements_text(capability_seed->'modes')),ARRAY(SELECT jsonb_array_elements_text(capability_seed->'input_roles')))
        ON CONFLICT (key) DO NOTHING;
        IF NOT EXISTS (SELECT 1 FROM catalog.capability WHERE id=(capability_seed->>'id')::uuid AND key=capability_seed->>'key' AND output_type=capability_seed->>'output_type' AND to_jsonb(modes)=capability_seed->'modes' AND to_jsonb(input_roles)=capability_seed->'input_roles') THEN
            RAISE EXCEPTION 'public capability seed conflict: %',capability_seed->>'key';
        END IF;
    END LOOP;
END $seed$;

